from lib import *
r=[]
r.append(R(3984,"आसान एयर फ्रायर झींगे","यह रेसिपी प्रक्रिया को तेज़ बनाने के लिए पके हुए झींगों का उपयोग करती है! अपनी पसंदीदा सब्जी के साथ परोसें।","4","2 औंस",
["1 पाउंड पके हुए मध्यम झींगे","1 बड़ी लहसुन की कली","2 बड़े चम्मच जैतून का तेल","1/4 छोटा चम्मच प्याज़ पाउडर","1/2 छोटा चम्मच काली मिर्च","1 छोटा चम्मच कम सोडियम वाली केजुन सीज़निंग","नॉनस्टिक कुकिंग स्प्रे"],
["झींगों को धोकर पेपर टॉवल से सुखा लें। लहसुन की कली को बारीक काटें।","एक कटोरे में जैतून का तेल, लहसुन, प्याज़ पाउडर, काली मिर्च, केजुन सीज़निंग और झींगे मिलाएँ।","रबर स्पैचुला से झींगों पर मिश्रण लगने तक मिलाएँ।","एयर फ्रायर को 400 डिग्री F पर पहले से गरम करें और ज़रूरत हो तो नॉनस्टिक कुकिंग स्प्रे करें।","झींगों को एयर फ्रायर में एक परत में सजाएँ और 3-4 मिनट पकाएँ। झींगों को पलटें और पूरी तरह पकने तक 2-3 मिनट और पकाते रहें।","तुरंत परोसें।"],
["इसे सलाद के साथ, पास्ता डिश के साथ या भुनी हुई सब्जियों के साथ परोसा जा सकता है।","ताज़े झींगों से भी बनाया जा सकता है, बस यह सुनिश्चित करें कि वे अंदर तक पूरी तरह पक जाएँ। पके और कच्चे दोनों झींगे पकने पर सिकुड़ जाते हैं।","सबसे कम नमक वाले पके हुए झींगे ढूँढें।"],
["3-1/2 मांस"]))
r.append(R(54926,"ग्रीक योगर्ट बेरी पारफ़े","सामग्री तैयारी उपयोगी सुझाव ग्रीक योगर्ट में अन्य योगर्ट की तुलना में अधिक प्रोटीन होता है। यह सुबह अंडों का अच्छा विकल्प हो सकता है। जोड़ी गई चीनी की मात्रा कम करने और इसे मधुमेह-अनुकूल बनाने के लिए आप शहद की जगह बिना चीनी वाला स्वीटनर इस्तेमाल कर सकते हैं।","1","1 पारफ़े",
["1/2 कप कम वसा वाला वनीला ग्रीक योगर्ट","1 छोटा चम्मच ताज़ा नींबू का रस","1 छोटा चम्मच शहद","1/4 कप जमी हुई कटी स्ट्रॉबेरी","मेसन जार या कटोरा"],
["नींबू का रस और शहद योगर्ट में मिलाएँ।","जमी हुई स्ट्रॉबेरी मेसन जार की तली में रखें। ऊपर योगर्ट का मिश्रण डालें।","जार को रात भर फ्रिज में रखें और सुबह उठा लें। आप स्ट्रॉबेरी को मिलाने के लिए चला सकते हैं, जो पिघलने के बाद एक अच्छी स्ट्रॉबेरी सॉस बना देंगी।"],
["ग्रीक योगर्ट में अन्य योगर्ट की तुलना में अधिक प्रोटीन होता है। यह सुबह अंडों का अच्छा विकल्प हो सकता है।","जोड़ी गई चीनी की मात्रा कम करने और इसे मधुमेह-अनुकूल बनाने के लिए आप शहद की जगह बिना चीनी वाला स्वीटनर इस्तेमाल कर सकते हैं।"],
["1 दूध","1 प्रोटीन","1/2 फल"]))
r.append(R(54928,"गार्डन वेजिटेबल पिटा","हमारे वेजी और मोज़ारेला पिटा के साथ एक झटपट, स्वस्थ और स्वादिष्ट भोजन का आनंद लें।","4","1 पिटा",
["1/2 बड़ा चम्मच जैतून का तेल","4 साबुत गेहूँ के पिटा, हर एक 6”","1 मध्यम लाल शिमला मिर्च","1 मध्यम तोरी (ज़ुकीनी)","1/2 कटा हुआ लाल प्याज़","1 लहसुन की कली, 3 औंस ताज़ा मोज़ारेला"],
["शिमला मिर्च, तोरी और प्याज़ को मोटा-मोटा काटें। लहसुन को बारीक काटें। कड़ाही में जैतून का तेल गरम करें। कटी हुई सब्जियाँ और लहसुन डालें। लगभग 10 मिनट पकाएँ और चलाते रहें।","सब्जियों को पिटा के ऊपर रखें। मोज़ारेला को हाथ से तोड़कर या टुकड़ों में काटकर हर पिटा में बराबर बाँटें और टैको की तरह मोड़ लें।","या फिर, पिटा को आधा चीर लें। सब्जियों को 8 पिटा आधों में बराबर बाँटें। मोज़ारेला को हाथ से तोड़कर या टुकड़ों में काटकर हर पिटा में बराबर बाँटें।"],
["ताज़ा चीज़ जैसे खाद्य पदार्थों में प्राकृतिक रूप से मौजूद फॉस्फोरस का हमारे शरीर द्वारा केवल आंशिक रूप से अवशोषण होता है। लगभग 40-60%, हर खाद्य पदार्थ और हर व्यक्ति अलग होता है।","आप ताज़ा मोज़ारेला स्लाइस वाले लॉग के रूप में पा सकते हैं। अपनी पसंद के अनुसार इसे पिटा में डालने के लिए तोड़ें या काटें।"],
["1/2 प्रोटीन","1-1/2 स्टार्च","1 सब्जी, मध्यम पोटैशियम"]))
r.append(R(54930,"वेजी टॉप्ड पोलेंटा","पोलेंटा और सब्जियों वाली DaVita की इस आसानी से बनने वाली रेसिपी के साथ एक रंगीन और संतोषजनक भोजन का आनंद लें।","4","2 पोलेंटा स्लाइस, 3/4 कप सब्जी मिश्रण और 1 औंस चीज़",
["2 छोटे चम्मच जैतून का तेल","1 मध्यम लाल शिमला मिर्च","1-1/2 कप तोरी (ज़ुकीनी)","2/3 कप कैनेलिनी बीन्स","1 छोटा चम्मच सूखा ओरेगैनो","1/8 छोटा चम्मच पिसी काली मिर्च","12 औंस पहले से पका पोलेंटा, 24 औंस के रोल से","नॉन-स्टिक कुकिंग स्प्रे","4 औंस ताज़ा पहले से कटा मोज़ारेला, 4 बड़े चम्मच DaVita की ईज़ी हनी मस्टर्ड बाल्सेमिक विनेग्रेट"],
["शिमला मिर्च और तोरी को मोटा-मोटा काटें। कड़ाही में जैतून का तेल गरम करें। कटी हुई सब्जियाँ डालें और लगभग 5 मिनट गरम करें। बीन्स डालें और लगभग 5 से 8 मिनट और पकाएँ और चलाते रहें।","दूसरे पैन पर कुकिंग स्प्रे करें और मध्यम आँच पर गरम करें। पोलेंटा को 8 स्लाइस में काटें और कड़ाही में भूरा करें। हर तरफ़ लगभग 4 मिनट।","परोसने के लिए, प्लेट में पोलेंटा के 2 स्लाइस रखें और ऊपर लगभग 3/4 कप सब्जियाँ डालें। ताज़ा मोज़ारेला को तोड़ें या काटें, प्रति सर्विंग लगभग 1 औंस होना चाहिए। ऊपर 1 बड़ा चम्मच ड्रेसिंग डालें। बची हुई ड्रेसिंग को सलाद के लिए या कच्ची सब्जियों के डिप के रूप में बचाकर रखें।"],
["ताज़ा चीज़ जैसे खाद्य पदार्थों में प्राकृतिक रूप से मौजूद फॉस्फोरस का हमारे शरीर द्वारा केवल आंशिक रूप से अवशोषण होता है। लगभग 40-60%, हर खाद्य पदार्थ और हर व्यक्ति अलग होता है।","पहले से पका पोलेंटा आमतौर पर 24 औंस की ट्यूब में आता है। इस रेसिपी में आधे का उपयोग करें और बाकी बाद में उपयोग के लिए बचाकर रखें।","इसे और अधिक मधुमेह-अनुकूल बनाने के लिए, वसा की मात्रा घटाने के लिए आप चीज़ कम कर सकते हैं।"],
["1/2 प्रोटीन","1 स्टार्च","1/2 सब्जी, मध्यम पोटैशियम","1 वसा"]))
r.append(R(54932,"तिलापिया विद ग्रिल्ड पाइनएप्पल सालसा","हमारी सरल बेक्ड तिलापिया आज़माएँ, जिसका चटपटी ग्रिल्ड पाइनएप्पल सालसा के साथ एकदम सही मेल है। एक किडनी-अनुकूल आनंद!","2","1 फ़िले, 1/4 कप सालसा",
["2 कच्चे तिलापिया फ़िले (हर एक 5 औंस)","1 छोटा चम्मच जैतून का तेल","नॉन-स्टिक कुकिंग स्प्रे","1/2 छोटा चम्मच पिसी काली मिर्च","1/2 कप ग्रिल्ड पाइनएप्पल सालसा"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। DaVita की ग्रिल्ड पाइनएप्पल सालसा तैयार करें। अलग रख दें।","बेकिंग शीट को फ़ॉइल से ढकें और उस पर नॉन-स्टिक कुकिंग स्प्रे करें। हर फ़िले पर जैतून का तेल बराबर लगाएँ और काली मिर्च छिड़कें।","15-20 मिनट बेक करें, जब तक मछली काँटे से नरम होकर परतों में न टूटने लगे। हर फ़िले को प्लेट पर रखें और ऊपर 1/4 कप ग्रिल्ड पाइनएप्पल सालसा डालें।"],
["प्राकृतिक रूप से मौजूद पोटैशियम का हमारे शरीर द्वारा केवल आंशिक रूप से अवशोषण होता है। लगभग 40-60%, हर खाद्य पदार्थ और/या व्यक्ति में अवशोषण अलग होता है।","आप तिलापिया की जगह अपनी पसंद की कोई अन्य सफ़ेद मछली इस्तेमाल कर सकते हैं।"],
["3-1/2 प्रोटीन","1/2 फल, कम पोटैशियम"]))
r.append(R(54941,"क्रंची साउथवेस्टर्न ब्रेकफ़ास्ट रैप","एक स्वादिष्ट, प्रोटीन से भरपूर नाश्ते का रैप। कीमा, फूले हुए अंडे और आलू को टॉर्टिला में मोड़कर सुनहरा भूरा होने तक सेंका गया।","6","1 रैप",
["2 मध्यम रसेट आलू","5 बड़े चम्मच वनस्पति तेल, बँटा हुआ","1 पाउंड कम चर्बी वाला बीफ़ कीमा","1 छोटा चम्मच पेपरिका","1 छोटा चम्मच लहसुन पाउडर","1 छोटा चम्मच पिसी काली मिर्च","1 छोटा चम्मच लाल मिर्च के गुच्छे","4 अंडे","3/4 कप तीखा चेडर चीज़, कद्दूकस किया हुआ","छह – 10” बुरिटो आकार की आटे की टॉर्टिला"],
["आलू को कद्दूकस करें। एक बर्तन में पानी उबालें और आलू डालकर 10-15 मिनट पकाएँ। निथारें और धोएँ, फिर एक बार और उबालें। निथार लें।","एक नॉनस्टिक पैन में मध्यम आँच पर 3 बड़े चम्मच वनस्पति तेल गरम करें। कद्दूकस किए आलू को पूरे पैन में पतली परत में फैलाएँ। कुरकुरा और सुनहरा होने तक, स्पैचुला से पलटते हुए, हर तरफ़ लगभग 3-4 मिनट पकाएँ। पैन से निकालकर अलग रख दें।","उसी पैन में मध्यम आँच पर कम चर्बी वाला कीमा डालें। पेपरिका, लहसुन पाउडर, पिसी काली मिर्च और लाल मिर्च के गुच्छे डालें। लगभग 7 मिनट पकाएँ, बराबर भूरा करने के लिए स्पैचुला से बार-बार पलटते रहें, जब तक मांस 160 °F तक न पहुँच जाए। अतिरिक्त तेल निथारकर फेंक दें। मांस को पैन से निकालकर अलग रख दें।","उसी पैन में धीमी आँच पर 1 बड़ा चम्मच वनस्पति तेल गरम करें। अंडों को एक छोटे कटोरे में तोड़कर फेंट लें। इन्हें पैन में डालें और अंडे जमने तक लेकिन सख़्त न होने तक (145°F) भुर्जी बनाएँ।","एक साफ़, बड़ी कड़ाही में मध्यम आँच पर टॉर्टिला को हर तरफ़ लगभग 30 सेकंड गरम करें। टॉर्टिला मुड़ने लायक होनी चाहिए।","आलू, कीमा, अंडे और चीज़ को हर टॉर्टिला के बीच में बराबर बाँटें। टॉर्टिला के ऊपरी हिस्से को बीच की ओर मोड़ें, फिर हर कोने को घड़ी की दिशा में बीच में मोड़ते जाएँ जब तक बंद रैप न बन जाए (5 मोड़)।","बड़ी कड़ाही में मध्यम आँच पर 1 बड़ा चम्मच वनस्पति तेल डालें। हर रैप को हर तरफ़ लगभग 30 सेकंड सुनहरा भूरा होने तक गरम करें।"],
["बीफ़ कीमे की जगह चिकन या टर्की का कीमा इस्तेमाल किया जा सकता है। पूरे अंडों की जगह अंडे के सफ़ेद भाग या अंडे के विकल्प (फॉस्फोरस योजक वाले से बचें) का इस्तेमाल किया जा सकता है।","रैप पहले से तैयार करके सुबह फिर से गरम किए जा सकते हैं। वे फ्रिज में 3-4 दिन तक चल सकते हैं, या फ्रीज़ करके फिर से गरम किए जा सकते हैं।","कम वसा वाले, मधुमेह-अनुकूल भोजन के लिए चिकन का विकल्प अपनाया जा सकता है, रैप (टॉर्टिला) हटाया जा सकता है और चेडर चीज़ हटाया जा सकता है।"],
["3 प्रोटीन","2-1/2 स्टार्च","2-1/2 वसा","1 डेयरी"]))
r.append(R(54945,"चिकन, फ्रूट एंड पॉपीसीड सलाद","एक स्वस्थ और स्वादिष्ट भोजन की तलाश में हैं? फलों के अनूठे अंदाज़ और स्वादिष्ट बिना चीनी वाली खसखस (पॉपीसीड) ड्रेसिंग के साथ यह आसानी से बनने वाला चिकन सलाद आज़माएँ।","1",None,
["1 पका हुआ चिकन ब्रेस्ट (3 औंस)","2 कप मीठा बटर लेट्यूस","1/2 कप कटी हुई स्ट्रॉबेरी","1/4 कप अनन्नास के टुकड़े, ताज़े या डिब्बाबंद","1/4 कप मैंडरिन संतरे (1 फ्रूट कप)","1-1/2 बड़े चम्मच बिना चीनी वाली खसखस (पॉपीसीड) ड्रेसिंग"],
["सलाद को निवाले के आकार के टुकड़ों में काटें, मैंडरिन संतरों का रस निथार दें। अगर डिब्बाबंद अनन्नास इस्तेमाल कर रहे हैं, तो अनन्नास का रस निथार दें।","पके चिकन ब्रेस्ट को पट्टियों में काटें। एक मध्यम कटोरे में लेट्यूस, फल और चिकन की परतें लगाएँ। ऊपर ड्रेसिंग डालें।"],
["बचा हुआ ग्रिल्ड या रोस्टेड पका चिकन ब्रेस्ट इस रेसिपी के साथ बहुत अच्छा काम करता है और एक आसान दोपहर का भोजन बन जाता है। अगर आप कम प्रोटीन वाला आहार ले रहे हैं, तो आधे चिकन ब्रेस्ट का उपयोग करें।","कोई दूसरी विनेग्रेट भी इस्तेमाल की जा सकती है। ऐसी ड्रेसिंग ढूँढें जिसमें 2 बड़े चम्मच की सर्विंग में 200 मिग्रा से कम सोडियम हो।"],
[]))
r.append(R(54947,"पैड थाई","घर के बने पैड थाई की चाहत है? बिल्कुल सही पके नूडल्स और स्वादिष्ट सॉस की हमारी सरल, किडनी-अनुकूल रेसिपी पाएँ।","3","1 कप",
["4 औंस राइस नूडल्स या ग्लूटेन-मुक्त के लिए ग्लास नूडल्स","3 बड़े चम्मच जैतून का तेल","8 औंस चिकन ब्रेस्ट (अन्य वैकल्पिक विकल्प: टोफू या छिले/नस निकाले हुए झींगे)","1/2 छोटा प्याज़","4 लहसुन की कलियाँ","2 अंडे","1 बड़ा चम्मच फ़िश सॉस","3 बड़े चम्मच ब्राउन शुगर","3 बड़े चम्मच राइस वाइन विनेगर","2 छोटे चम्मच कम सोडियम वाला कोकोनट एमिनोज़","1 नींबू (लाइम)","1-1/2 कप ताज़े बीन स्प्राउट्स (अंकुरित फलियाँ)"],
["राइस नूडल्स को एक उथले पैन में रखकर उबलते पानी से ढककर 4-7 मिनट भिगोएँ, बीच-बीच में चलाते हुए, जब तक वे अल डेंटे (हल्के कड़क) न हो जाएँ; निथारें, ठंडे पानी से धो लें।","प्याज़ को बारीक काटें और लहसुन को मोटा-मोटा काटें। दो अंडों को कटोरे में काँटे से फेंटें और अलग रख दें। पैड थाई सॉस बनाएँ: एक छोटे कटोरे में फ़िश सॉस, राइस विनेगर, ब्राउन शुगर और कोकोनट एमिनोज़ को फेंटें। अलग रख दें।","चिकन को बहुत पतली पट्टियों में काटें। (अगर टोफू इस्तेमाल कर रहे हैं: टोफू को पेपर टॉवल से कसकर दबाते हुए सुखाएँ। टोफू को ¾ इंच के टुकड़ों में काटें, और अतिरिक्त कुरकुरे टोफू के लिए थोड़े कॉर्न स्टार्च में लपेटें। अगर झींगे इस्तेमाल कर रहे हैं: पेपर टॉवल से सुखा लें।)","एक बड़े सॉसपैन या कड़ाही में मध्यम-तेज़ आँच पर 1 बड़ा चम्मच तेल गरम करें। मसाला लगे चिकन को सेकें। (अगर झींगे या टोफू इस्तेमाल कर रहे हैं, तो उन्हें भी पूरी तरह पकने तक इसी तरह पकाएँ।) अलग रख दें।","कड़ाही या बड़ी कढ़ाई में मध्यम आँच पर थोड़ा और तेल गरम करें, प्याज़ और लहसुन डालकर 2-3 मिनट भूनें। प्याज़ के मिश्रण को एक तरफ़ सरकाएँ, और तेल डालें और अंडे डालें। भुर्जी बनाएँ और उसे छोटे टुकड़ों में तोड़कर एक तरफ़ कर दें। और तेल डालें, और नूडल्स डालें, 2-3 मिनट भूनें जब तक नूडल्स नरम और लचीले न हो जाएँ और थोड़े कुरकुरे भी हो जाएँ।","पैड थाई सॉस डालें और सबको साथ चलाएँ और 1-2 मिनट पकाएँ, फिर पका हुआ चिकन (झींगे या टोफू) डालें और गरम होने तक भूनें। थोड़ा नींबू का रस निचोड़ें। आँच बंद करें।","1/2 बीन स्प्राउट्स डालकर उछालें। एक बार और उछालें और तुरंत परोसें। 2 प्लेटों में बाँटें। वैकल्पिक टॉपिंग के रूप में लाल मिर्च के गुच्छे और/या हरा प्याज़ डाला जा सकता है।"],
["कोकोनट एमिनोज़ में सोडियम अलग-अलग होता है, जो सबसे कम मिले वही चुनें। इसे अधिक मधुमेह-अनुकूल बनाने के लिए नूडल्स कम करें और ब्राउन शुगर की जगह चीनी का विकल्प इस्तेमाल करें।","इस व्यंजन में सोडियम थोड़ा अधिक है लेकिन यह बाहर से मँगाए गए पैड थाई भोजन का लगभग ½ है, जिसमें सोडियम लगभग 1300 मिग्रा तक पहुँच सकता है।"],
["3 प्रोटीन","2 स्टार्च","1/2 उच्च कैलोरी","1 सब्जी, कम पोटैशियम","1 वसा"]))
r.append(R(54949,"हैमबर्गर सलाद","इस झटपट और आसान सलाद में चीज़बर्गर के सारे क्लासिक स्वादों का आनंद लें! चीज़ की सीमित मात्रा इसे किडनी-अनुकूल बनाए रखने में मदद करती है।","4","1-1/2 कप",
["1/2 कप मेयोनेज़","4 छोटे चम्मच तैयार सरसों (प्रिपेयर्ड मस्टर्ड)","2 बड़े चम्मच कटे डिल अचार","1 बड़ा चम्मच सफ़ेद सिरका","1 छोटा चम्मच चीनी","1 बड़ा चम्मच कटा प्याज़","1/2 छोटा चम्मच स्मोक्ड पेपरिका","1 पाउंड कम चर्बी वाला बीफ़ कीमा (7-10%)","1 छोटा चम्मच पिसी काली मिर्च","4 कप कटा आइसबर्ग लेट्यूस","1/2 कप प्याज़","1/2 कप कद्दूकस किया तीखा चेडर"],
["मेयोनेज़, सरसों, कटे अचार, सिरका, चीनी, कटा प्याज़ और पेपरिका मिलाएँ और अलग रख दें।","सॉटे पैन को मध्यम आँच पर गरम करें और कीमा डालें, गुठलियों को तोड़ते हुए पूरी तरह पकने तक पकाएँ। काली मिर्च डालकर पैन में मिलाएँ।","जब कीमा पक रहा हो, तब लेट्यूस काटें और प्याज़ के स्लाइस काटें।","परोसने के लिए तैयार होने पर लेट्यूस, चीज़ और प्याज़ मिलाएँ। इसे 4 कटोरों में बाँटा जा सकता है, या आप बिना इस्तेमाल किए हिस्से बचाकर रख सकते हैं।","हर कटोरे में कीमे का लगभग 1/4 हिस्सा डालें और ड्रेसिंग की धार डालें। तुरंत परोसें।"],
["आप सामग्री को अलग-अलग रखकर बचे हुए के रूप में इस्तेमाल कर सकते हैं। अगर आप कम प्रोटीन वाला आहार ले रहे हैं, तो केवल 8 औंस बीफ़ इस्तेमाल करें।","हल्का (लाइट) मेयोनेज़ इस्तेमाल किया जा सकता है, लेकिन सबसे कम सोडियम वाला संस्करण ढूँढें।"],
["4 प्रोटीन","1 सब्जी, कम पोटैशियम","1-1/2 वसा"]))
r.append(R(54951,"बुरिटो बाउल","ताज़े और आसान सप्ताह के दिन के रात के खाने की तलाश में हैं? इस किडनी-अनुकूल चिकन बुरिटो बाउल रेसिपी में चटपटी चिपोटले ड्रेसिंग है।","4","1 बाउल",
[("ड्रेसिंग","1/2 कप रेड वाइन विनेगर"),("ड्रेसिंग","2 बड़े चम्मच शहद"),("ड्रेसिंग","3/4 कप जैतून का तेल"),("ड्रेसिंग","1/2 छोटा चम्मच सूखा ओरेगैनो"),("ड्रेसिंग","1/8 छोटा चम्मच पिसा जीरा"),("ड्रेसिंग","अडोबो सॉस में 1 चिपोटले मिर्च"),("ड्रेसिंग","1 बड़ी लहसुन की कली"),("ड्रेसिंग","1/4 कप ताज़ा धनिया"),("बुरिटो बाउल","2 बिना हड्डी और बिना त्वचा वाली चिकन जाँघें (या चिकन ब्रेस्ट)"),("बुरिटो बाउल","1 बड़ी पीली शिमला मिर्च"),("बुरिटो बाउल","1 तोरी (ज़ुकीनी)"),("बुरिटो बाउल","1 छोटा बैंगनी प्याज़"),("बुरिटो बाउल","1-1/2 बड़े चम्मच जैतून का तेल"),("बुरिटो बाउल","1 छोटा चम्मच लहसुन पाउडर"),("बुरिटो बाउल","1 छोटा चम्मच प्याज़ पाउडर"),("बुरिटो बाउल","1 कप पका हुआ Minute सफ़ेद चावल"),("बुरिटो बाउल","1 रोमेन लेट्यूस")],
["सारी ड्रेसिंग की सामग्री को फ़ूड प्रोसेसर या ब्लेंडर में डालें, और अच्छी तरह मिलने तक ब्लेंड करें (इससे 1 1/4 कप बनना चाहिए)।","चिकन की जाँघों पर 1/4 कप ड्रेसिंग से मसाला लगाएँ, दोनों तरफ़ ब्रश से लगाएँ।","मसाला लगे चिकन को ग्रिल पर, या घर के अंदर ग्रिल पैन में पूरी तरह पकने तक ग्रिल करें। स्लाइस में काटें। शिमला मिर्च, प्याज़ और तोरी को पतली पट्टियों में काटें।","एक मध्यम सॉटे पैन में 1-1/2 बड़े चम्मच तेल डालें, मध्यम आँच पर गरम करें, प्याज़, शिमला मिर्च और तोरी के स्लाइस डालें।","सब्जियों को मध्यम आँच पर 3 मिनट भूनें, प्याज़ और लहसुन पाउडर डालें, और चलाएँ जब तक सब्जियों पर मसाला बराबर न लग जाए। सब्जियों को नरम होने तक पकाएँ।","पैकेट पर दिए निर्देशों के अनुसार सफ़ेद चावल पकाएँ ताकि एक कप बने। लेट्यूस को पतली पट्टियों में काटें।","बाउल तैयार करने के लिए हर बाउल में 1 कप लेट्यूस, 1/2 कप कटा चिकन, 1/4 कप सफ़ेद चावल, 1/4 कप भुनी सब्जियाँ डालें और ऊपर 3 बड़े चम्मच ड्रेसिंग डालें। वैकल्पिक: चाहें तो हर बाउल के ऊपर 2 टॉर्टिला चिप्स डाल सकते हैं।"],
["सब्जियाँ पकाने के लिए जैतून के तेल की जगह कुकिंग स्प्रे इस्तेमाल किया जा सकता है। मधुमेह-अनुकूल ड्रेसिंग के लिए शहद की जगह चीनी का विकल्प इस्तेमाल किया जा सकता है।","इस व्यंजन में पोटैशियम अधिक है लेकिन यह सब्जियों जैसे प्राकृतिक स्रोतों से आता है। हमारा शरीर केवल लगभग 40-60% अवशोषित करता है। सब्जियाँ अन्य पोषक तत्व और फ़ाइबर भी देती हैं। यह एक-डिश भोजन भी है।","अगर चाहें; आप 1/4 कप कम सोडियम वाली डिब्बाबंद काली बीन्स (धोकर और निथारकर) डाल सकते हैं। इससे लगभग 80 मिग्रा सोडियम, 180 मिग्रा पोटैशियम और 64 मिग्रा फॉस्फोरस जुड़ेगा। ध्यान रखें कि बीन्स में पाए जाने वाले प्राकृतिक पोटैशियम/फॉस्फोरस में से हमारा शरीर केवल लगभग 40-60% अवशोषित करता है।"],
["1 प्रोटीन","1 स्टार्च","2 सब्जियाँ, उच्च पोटैशियम","1/2 उच्च कैलोरी","5 वसा"]))
r.append(R(54953,"ट्यूना मेल्ट सैंडविच","एक स्वादिष्ट और किडनी-अनुकूल ट्यूना मेल्ट का आनंद लें! इस आसानी से बनने वाली रेसिपी में कम सोडियम वाली ट्यूना और ताज़ी सब्जियाँ हैं।","2","1 सैंडविच",
["2 बड़े चम्मच लाइट मेयो","1/4 छोटा चम्मच काली मिर्च","8 औंस कम सोडियम वाली या बिना नमक की ट्यूना (दो 5-औंस के डिब्बे)","2 औंस मॉन्टेरी जैक","छोटे टमाटर के 2 स्लाइस","1/2 छोटा खीरा","1/2 छोटी हरी शिमला मिर्च","1/2 छोटा लाल प्याज़","1/2 कप रोमेन लेट्यूस","2 हैमबर्गर बन"],
["ट्यूना को निथार लें। एक कटोरे में मेयोनेज़, काली मिर्च और ट्यूना मिलाएँ। मिश्रण को हैमबर्गर बन के निचले हिस्सों में बराबर बाँटें।","ट्यूना के मिश्रण पर चीज़ रखें, ओवन को 350F पर पहले से गरम करें। ट्यूना वाले हिस्से और बन के ऊपरी हिस्से (सीधा ऊपर की ओर) को बेकिंग शीट पर रखें। 15 मिनट बेक करें।","इस बीच खीरा, हरी शिमला मिर्च और लाल प्याज़ के स्लाइस काटें। लेट्यूस को बारीक काटें या कतरें। सैंडविच को ओवन से निकालें और सब्जियाँ ऊपर बराबर परतों में रखें। प्लेट में रखकर परोसें। दूसरा सैंडविच किसी और दिन के लिए बचाया जा सकता है या परिवार या दोस्तों के साथ बाँटा जा सकता है।"],
["इस रेसिपी में पोटैशियम अधिक है, लेकिन यह सब्जियों और ट्यूना से प्राकृतिक रूप से आता है। सब्जियों के स्रोतों से हमारा शरीर प्राकृतिक पोटैशियम का केवल लगभग 40-60% अवशोषित करता है।","अगर आप कम प्रोटीन वाला आहार ले रहे हैं, तो ट्यूना की मात्रा आधी या एक तिहाई कम कर सकते हैं।"],
["3-1/2 प्रोटीन","1-1/2 स्टार्च","1-1/2 डेयरी"]))
r.append(R(54955,"स्ट्रॉबेरी मिल्कशेक","इस ट्रीट से अपनी मिठास की चाहत पूरी करें! यह मलाईदार स्ट्रॉबेरी ड्रिंक एक किडनी-अनुकूल, भरपूर मिल्कशेक है और बिना चीनी का भी है।","1","10 औंस",
["1/2 कप जमी हुई स्ट्रॉबेरी","2 बड़े चम्मच हैवी क्रीम","1 बड़ा चम्मच मॉन्क फ्रूट तरल स्वीटनर","8 औंस नारियल का दूध"],
["सारी सामग्री ब्लेंडर में डालें।","चिकना होने तक ब्लेंड करें।","मज़ेदार गिलास में डालें, एक स्ट्रॉबेरी से सजाएँ और आनंद लें!"],
["डेयरी-मुक्त विकल्प के लिए हैवी क्रीम की जगह नारियल क्रीम इस्तेमाल की जा सकती है।","फ्रिज में रखा जाने वाला नारियल का दूध दुकान के कूलर में दूध के विकल्पों के पास मिलता है।"],
["1/2 फल, कम पोटैशियम","3 वसा"]))
r.append(R(54957,"बेक्ड डोनट्स 5 तरीकों से","आज ही स्वादिष्ट घर के बने डोनट्स का एक बैच बेक करें! यह आसान रेसिपी कुछ ही मिनटों में बेक हो जाती है और आप अपनी पसंदीदा टॉपिंग के साथ इसे अपने अनुसार बना सकते हैं।","16","1 डोनट",
["4 बड़े चम्मच मक्खन, बिना नमक का","1/4 कप वनस्पति तेल","1/2 कप दानेदार चीनी","1/3 कप हल्की ब्राउन शुगर, दबाकर भरी हुई","2 बड़े अंडे, कमरे के तापमान पर","1-1/2 छोटे चम्मच बेकिंग पाउडर","1/4 छोटा चम्मच बेकिंग सोडा","1/2 से 1 छोटा चम्मच दालचीनी, स्वादानुसार (वैकल्पिक)","3/4 छोटा चम्मच नमक","1 छोटा चम्मच शुद्ध वनीला एक्सट्रैक्ट","2-2/3 कप मैदा (ऑल-पर्पज़ फ़्लोर)","1 कप नॉन-डेयरी दूध","दालचीनी और चीनी: एक गैलन ज़िप बैग में 1 कप दानेदार सफ़ेद चीनी और 1 बड़ा चम्मच दालचीनी मिलाएँ। गरम डोनट्स को बैग में डालें, बंद करें और परत चढ़ाने के लिए हल्के से हिलाएँ।","क्लासिक ग्लेज़्ड: एक कटोरे में 1 कप पाउडर चीनी, 1/3 कप नॉन-डेयरी दूध, 1/2 छोटा चम्मच शुद्ध वनीला एक्सट्रैक्ट मिलाएँ। चिकना होने तक फेंटें। गरम डोनट्स को ग्लेज़ में डुबोएँ। सूखने के लिए कम से कम 30 मिनट तार की जाली पर रखें।","मेपल कॉफ़ी ग्लेज़: 1-1/2 कप पाउडर चीनी, 1 छोटा चम्मच मेपल एक्सट्रैक्ट, 1/2 कप बनी हुई कॉफ़ी और 2 बड़े चम्मच पिघला मक्खन मिलाएँ। चिकना होने तक फेंटें। गरम डोनट्स को ग्लेज़ में डुबोएँ। सूखने के लिए कम से कम 30 मिनट तार की जाली पर रखें।","बेरी फ़्रॉस्टेड: 1 कप पाउडर चीनी, 2 बड़े चम्मच बेरी जैम (स्ट्रॉबेरी, रास्पबेरी या ब्लूबेरी) और 1 छोटा चम्मच पानी मिलाएँ। चिकना होने तक फेंटें। गरम डोनट्स को फ़्रॉस्टिंग में डुबोएँ और तार की जाली पर रखें। 30 मिनट सूखने दें।","कॉन्फ़ेटी फ़्रॉस्टेड: 1 कप पाउडर चीनी, 1 बड़ा चम्मच नॉन-डेयरी दूध और 1-2 बूँद खाने का रंग मिलाएँ। चिकना होने तक फेंटें। गरम डोनट्स को फ़्रॉस्टिंग में डुबोएँ और तार की जाली पर रखें। ऊपर स्प्रिंकल्स डालें। 30 मिनट सूखने दें।"],
["ओवन को 375°F पर पहले से गरम करें। दो मानक डोनट पैन या एक मानक मफ़िन टिन में हल्की चिकनाई लगाएँ (सुझाव देखें)।","एक मिक्सिंग बाउल में मक्खन, वनस्पति तेल, ब्राउन शुगर और 1/2 कप दानेदार चीनी को चिकना होने तक फेंटें। अंडे डालें, साथ फेंटें।","बेकिंग पाउडर, बेकिंग सोडा, 1/2 से 1 छोटा चम्मच दालचीनी, नमक और वनीला मिलाकर चलाएँ।","मिश्रण में मैदा और दूध बारी-बारी से डालें, मैदे से शुरू करें और मैदे पर ही समाप्त करें, जब तक सब मिल न जाए। घोल गाढ़ा होगा।","घोल को चम्मच से टिन में 3/4 तक भरें। 10-12 मिनट बेक करें। निकालें, और थोड़ा ठंडा होने के लिए 5-7 मिनट रुकें। पलटकर तार की जाली पर रखें।","अपनी पसंद की टॉपिंग (या कई टॉपिंग) तैयार करें। हर टॉपिंग 12 डोनट्स के लिए पर्याप्त बनती है।","हवाबंद डिब्बे में 3 दिन तक रखें।"],
["डोनट पैन नहीं है? फ़ॉइल का एक लंबा टुकड़ा (लगभग 9 इंच) लें। इसे लंबे आयत में मोड़ें और फिर अपने मनचाहे डोनट के छेद के आकार का एक गोला बनाएँ। 12 बार दोहराएँ। इन्हें अपने मफ़िन टिन के हर खाने में रखें। फ़ॉइल को बीच में रखें और फ़ॉइल के चारों ओर घोल चम्मच से डालें।","डोनट के आकार की परवाह नहीं? बस मफ़िन टिन में बेक करें। बेकिंग समय में 3-4 मिनट जोड़ने होंगे। हर टॉपिंग 12 डोनट्स के लिए पर्याप्त बनती है।"],
["1 स्टार्च","1-1/2 उच्च कैलोरी","1 वसा"]))
save(6,r)
